<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=$_POST['status']??'';$note=trim($_POST['admin_note']??'');if(!$id||!in_array($status,['Pending','Approved','Rejected','Cancelled'],true)||mb_strlen($note)>1000)$error='Invalid booking update. Check the status and note length.';else{try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM bookings WHERE id=? FOR UPDATE');$s->execute([$id]);$b=$s->fetch();if(!$b)throw new RuntimeException('Booking not found.');if($status==='Approved'){$s=$pdo->prepare("SELECT COUNT(*) FROM bookings WHERE drum_id=? AND id<>? AND status='Approved' AND start_at < ? AND end_at > ?");$s->execute([$b['drum_id'],$id,$b['end_at'],$b['start_at']]);if((int)$s->fetchColumn()>0)throw new RuntimeException('Cannot approve: another approved booking overlaps this session.');}if($b['status']==='Cancelled'&&$status!=='Cancelled')throw new RuntimeException('Cancelled bookings cannot be reopened.');$s=$pdo->prepare('UPDATE bookings SET status=?,admin_note=? WHERE id=?');$s->execute([$status,$note,$id]);$pdo->commit();flash('success','Booking updated.');redirect('bookings.php');}catch(RuntimeException $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();error_log($ex->__toString());$error='Could not update booking. Please try again.';}}}
$filter=$_GET['status']??'';$allowed=['Pending','Approved','Rejected','Cancelled'];$sql='SELECT b.*,u.name client_name,u.email,u.phone,d.name drum_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN drums d ON d.id=b.drum_id';$params=[];if(in_array($filter,$allowed,true)){$sql.=' WHERE b.status=?';$params[]=$filter;}$sql.=' ORDER BY CASE b.status WHEN \'Pending\' THEN 0 ELSE 1 END,b.start_at DESC';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();page_header('Manage bookings');?><div class="toolbar"><p class="muted">Review requests and approve or reject sessions.</p><form method="get" class="filter"><label for="status">Filter</label><select id="status" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach($allowed as $st):?><option <?=($filter===$st?'selected':'')?> value="<?=e($st)?>"><?=e($st)?></option><?php endforeach;?></select></form></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(!$rows):?><div class="empty"><p>No bookings found.</p></div><?php else:?><div class="stack"><?php foreach($rows as $b):?><article class="booking-card"><div class="detail-head"><div><h2><?=e($b['drum_name'])?></h2><p class="muted">Booking #<?=(int)$b['id']?> · Requested <?=e(date('M j, Y',strtotime($b['created_at'])))?></p></div><span class="<?=e(booking_status_class($b['status']))?>"><?=e($b['status'])?></span></div><div class="grid two booking-info"><p><strong>Client:</strong> <?=e($b['client_name'])?></p><p><strong>Email:</strong> <?=e($b['email'])?></p><p><strong>Phone:</strong> <?=e($b['phone']?:'Not provided')?></p><p><strong>Session:</strong> <?=e(date('M j, Y g:i A',strtotime($b['start_at'])))?> – <?=e(date('g:i A',strtotime($b['end_at'])))?></p><p><strong>Purpose:</strong> <?=e($b['purpose'])?></p><p><strong>Total:</strong> <?=money($b['total_price'])?></p><p class="span-2"><strong>Client notes:</strong> <?=nl2br(e($b['notes']?:'None'))?></p></div><form method="post" class="admin-update"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$b['id']?>"><label>Admin note<textarea name="admin_note" maxlength="1000" rows="2"><?=e($b['admin_note'])?></textarea></label><div class="actions"><label class="inline-label">Status<select name="status"><?php foreach($allowed as $st):?><option value="<?=e($st)?>" <?=($b['status']===$st?'selected':'')?> <?=($b['status']==='Cancelled'&&$st!=='Cancelled'?'disabled':'')?>><?=e($st)?></option><?php endforeach;?></select></label><button class="button small" type="submit">Save update</button></div></form></article><?php endforeach;?></div><?php endif;?><?php page_footer();?>
